use aap::caps::state_read;

/// Key within the `subscriptions` store that holds the newline-separated feed URLs.
const SUBSCRIPTIONS_KEY: &str = "urls";

struct Node;

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        // The store is read-only and has no enumeration, so the one key we know
        // is looked up directly. An absent key means the contract's `present(urls)`
        // cannot be discharged, so the node refuses to produce an output rather
        // than inventing one.
        let raw = match state_read::get(SUBSCRIPTIONS_KEY) {
            Some(raw) => raw,
            None => panic!("subscriptions: key `{}` is not present", SUBSCRIPTIONS_KEY),
        };

        let urls: Vec<String> = raw
            .lines()
            .map(str::trim)
            .filter(|line| !line.is_empty())
            .map(String::from)
            .collect();

        // `present(urls)`: the output must carry at least one URL.
        if urls.is_empty() {
            panic!("subscriptions: no URLs present under key `{}`", SUBSCRIPTIONS_KEY);
        }

        SubscriptionList { urls }
    }
}

export!(Node);
